import { glyphs, ligature, viewBox } from "./name-paths";

const [minX, minY, width, height] = viewBox.split(" ").map(Number) as [number, number, number, number];

/**
 * "Iury / Umbelino" as one lettered mark (paths generated by scripts/lettering.py).
 * The y and the b are a single outline: the y's stem runs straight down into the
 * b's stem. Decorative for assistive tech: the h1 around it carries the name.
 *
 * The ligature sits behind a clip rect the size of the whole viewBox, so at rest
 * nothing is clipped; HeroMotion animates the rect's height to draw the y down
 * into the b.
 */
export function NameMark({ className }: { className?: string }) {
  return (
    <svg
      viewBox={viewBox}
      className={className}
      aria-hidden="true"
      focusable="false"
      fill="currentColor"
      overflow="visible"
      data-namemark
    >
      <defs>
        <clipPath id="namemark-draw" clipPathUnits="userSpaceOnUse">
          <rect data-join-clip x={minX} y={minY} width={width} height={height} />
        </clipPath>
      </defs>
      {glyphs.map((g) => (
        <path key={g.id} d={g.d} data-glyph={g.id} data-line={g.line} />
      ))}
      <path d={ligature.d} data-join clipPath="url(#namemark-draw)" />
    </svg>
  );
}
